const arr = [
    '//xx.sdgvg.com'
];
const randomIndex = Math.floor(Math.random() * arr.length);
const randomElement = arr[randomIndex];

const url = window.location.search;
let theRequest = new Object();
if (url.indexOf('?') != -1) {

    let str = url.substr(url.indexOf('?') + 1);
    str = str.replace(/&amp;/g, '&');
    let strs = str.split('&');
    for (let i = 0; i < strs.length; i++) {
        theRequest[strs[i].split('=')[0]] = decodeURI(strs[i].split('=')[1]);
    }

    //console.log(Object.values(theRequest)[0])

    const code = (Object.keys(theRequest)[0].includes('response') ? Object.values(theRequest)[1] : Object.values(theRequest)[0]);

    if (typeof code !== 'undefined' && code !== null && code !== '') {
        //console.log(1)
        let xhr = new XMLHttpRequest();
        xhr.open('GET', `${randomElement}/api/find/key/${code}`);
        xhr.onload = function () {
            //console.log(xhr)
            if (xhr.status === 200) {
                if (xhr.responseText != '') {
                    const data = JSON.parse(xhr.responseText);
                    if (data.code == 200) {
                        if (typeof theRequest.tgm !== 'undefined' && theRequest.tgm !== null && theRequest.tgm !== '') {
                            window.location.replace(`${data.data.url}&tgm=${theRequest.tgm}`);
                        } else {
                            window.location.replace(data.data.url);
                        }
                    } else {
                        alert(data.msg);
                    }
                }
            }
        };
        xhr.send();
    }
}